using System.Text.Json.Nodes;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using YamlDotNet.RepresentationModel;
var passed = 0;
void Check(string name, Action action) { action(); Console.WriteLine("PASS " + name); passed++; }
void Denied(Action action) { try { action(); } catch (Exception e) when (e is UnauthorizedAccessException or IOException) { return; } throw new Exception("Unsafe input was accepted"); }
var dir = Path.Combine(Path.GetTempPath(), "luma-service-policy-" + Guid.NewGuid());
try {
    Check("fixed private controller replaces caller credentials", () => { var result = ConfigPolicy.Rewrite("proxies: []\nexternal-controller: 0.0.0.0:9090\nsecret: public\n", dir, 32123, "private"); if (!result.Contains("127.0.0.1:32123") || result.Contains("public")) throw new Exception(result); });
    Check("LAN intent retained", () => { if (!ConfigPolicy.Rewrite("allow-lan: true\nbind-address: '*'\nproxies: []", dir, 1, "x").Contains("allow-lan: true")) throw new Exception(); });
    Check("unknown root fails closed", () => Denied(() => ConfigPolicy.Rewrite("arbitrary-new-file-option: danger", dir, 1, "x")));
    Check("arbitrary provider file denied", () => Denied(() => ConfigPolicy.Rewrite("proxy-providers: {p: {type: file, path: C:/Windows/secrets}}", dir, 1, "x")));
    Check("submitted local provider becomes protected cache asset", () => { var name = "./providers/" + new string('a', 64) + ".yaml"; var result = ConfigPolicy.Rewrite("proxy-providers: {p: {type: file, path: '" + name + "'}}", dir, 1, "x", null, new() { [name] = Path.Combine(dir, "cache", "local.yaml") }); if (result.Contains("./providers/")) throw new Exception(result); });
    Check("local rule provider payload accepted", () => ConfigPolicy.LocalProviderContent("payload: [example.invalid]", dir));
    Check("local provider invalid root rejected", () => Denied(() => ConfigPolicy.LocalProviderContent("arbitrary: []", dir)));
    Check("HTTP proxy provider requires validation", () => Denied(() => ConfigPolicy.Rewrite("proxy-providers: {p: {type: http, url: https://example.invalid/a}}", dir, 1, "x")));
    Check("validated proxy provider becomes protected local file", () => { var result = ConfigPolicy.Rewrite("proxy-providers: {p: {type: http, url: https://example.invalid/a, path: ../../bad}}", dir, 1, "x", new() { ["p"] = Path.Combine(dir, "cache", "safe.yaml") }); if (!result.Contains("type: file") || result.Contains("example.invalid")) throw new Exception(result); });
    Check("rule provider cache path rewritten", () => { var result = ConfigPolicy.Rewrite("rule-providers: {r: {type: http, url: https://example.invalid/r, path: ../../bad}}", dir, 1, "x"); if (result.Contains("../../bad")) throw new Exception(); });
    Check("HTTP provider URL protocol constrained", () => Denied(() => ConfigPolicy.ProxyProviderSources("proxy-providers: {p: {type: http, url: file:///C:/Windows/secrets}}")));
    var bridgeUrl="http://127.0.0.1:32123/luma-provider/"+new string('a',64)+"/"+new string('b',64);
    Check("authenticated local provider bridge preserves refresh interval",()=>{var sources=ConfigPolicy.ProxyProviderSources("proxy-providers: {p: {type: http, interval: 30, url: "+bridgeUrl+"}}"); if(sources["p"].Url!=bridgeUrl||sources["p"].Interval!=30) throw new Exception();});
    Check("privileged proxy provider cannot fetch upstream directly",()=>Denied(()=>ConfigPolicy.ProxyProviderSources("proxy-providers: {p: {type: http, url: https://example.invalid/provider}}")));
    Check("provider bridge path and query injection denied",()=>{foreach(var u in new[]{bridgeUrl+"?url=x",bridgeUrl.Replace("127.0.0.1","localhost"),bridgeUrl.Replace("/luma-provider/","/other/")}) Denied(()=>ConfigPolicy.ProxyProviderSources("proxy-providers: {p: {type: http, url: '"+u+"'}}"));});
    Check("negative provider interval denied",()=>Denied(()=>ConfigPolicy.ProxyProviderSources("proxy-providers: {p: {type: http, interval: -1, url: "+bridgeUrl+"}}")));
    Check("remote proxy provider content inspected", () => Denied(() => ConfigPolicy.ProviderContent("proxies: [{name: x, type: http, ca-file: C:/Windows/secrets}]", dir)));
    Check("provider arbitrary root rejected", () => Denied(() => ConfigPolicy.ProviderContent("proxies: []\nexternal-controller: 0.0.0.0:1", dir)));
    Check("provider normal WebSocket path retained", () => ConfigPolicy.ProviderContent("proxies: [{name: x, type: vless, ws-opts: {path: /transport}}]", dir));
    Check("inline certificate path rejected", () => Denied(() => ConfigPolicy.Rewrite("proxies: [{type: http, certificate: C:/Windows/secrets}]", dir, 1, "x")));
    using var tlsKey = RSA.Create(2048);
    using var tlsCert = new CertificateRequest("CN=Luma Fixture", tlsKey, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1).CreateSelfSigned(DateTimeOffset.UtcNow.AddDays(-1), DateTimeOffset.UtcNow.AddDays(1));
    string TlsYaml(string cert, string key) { var root = new YamlMappingNode { { "proxies", new YamlSequenceNode(new YamlMappingNode { { "name", "fixture" }, { "type", "http" }, { "certificate", new YamlScalarNode(cert) }, { "private-key", new YamlScalarNode(key) } }) } }; using var output = new StringWriter(); new YamlStream(new YamlDocument(root)).Save(output, false); return output.ToString(); }
    var tlsYaml = TlsYaml(tlsCert.ExportCertificatePem(), tlsKey.ExportPkcs8PrivateKeyPem());
    Check("inline TLS client certificate and private key accepted", () => ConfigPolicy.Rewrite(tlsYaml, dir, 1, "x"));
    Check("provider inline TLS credentials accepted", () => ConfigPolicy.ProviderContent(tlsYaml, dir));
    Check("TLS private key file path denied in root and providers", () => { var value = TlsYaml(tlsCert.ExportCertificatePem(), "C:/Windows/secrets"); Denied(() => ConfigPolicy.Rewrite(value, dir, 1, "x")); Denied(() => ConfigPolicy.ProviderContent(value, dir)); });
    Check("TLS mismatched PEM labels denied", () => Denied(() => ConfigPolicy.Rewrite(TlsYaml(tlsKey.ExportPkcs8PrivateKeyPem(), tlsCert.ExportCertificatePem()), dir, 1, "x")));
    Check("TLS malformed PEM and trailing paths denied", () => { foreach (var value in new[] { "-----BEGIN CERTIFICATE-----\nYmFk\n-----END CERTIFICATE-----", tlsCert.ExportCertificatePem() + "\nC:/Windows/secrets" }) Denied(() => ConfigPolicy.ProviderContent(TlsYaml(value, tlsKey.ExportPkcs8PrivateKeyPem()), dir)); });
    Check("TLS mismatched client key denied", () => { using var other = RSA.Create(2048); Denied(() => ConfigPolicy.Rewrite(TlsYaml(tlsCert.ExportCertificatePem(), other.ExportPkcs8PrivateKeyPem()), dir, 1, "x")); });
    Check("TLS nested provider key paths denied", () => Denied(() => ConfigPolicy.ProviderContent("proxies: [{name: x, type: http, opts: {private-key: C:/Windows/secrets}}]", dir)));
    Check("file references nested deeply rejected", () => Denied(() => ConfigPolicy.Rewrite("proxies: [{type: x, opts: {private-key-file: C:/secret}}]", dir, 1, "x")));
    Check("normal read endpoints allowed", () => { foreach (var p in new[] { "/version", "/configs", "/proxies", "/connections", "/rules", "/providers/proxies/p", "/proxies/p/delay?url=http%3A%2F%2F127.0.0.1" }) ApiPolicy.Validate(p, "GET", null); });
    Check("provider-specific node healthcheck allowed", () => ApiPolicy.Validate("/providers/proxies/Provider%20A/Node%20A/healthcheck?timeout=5000&url=http%3A%2F%2F127.0.0.1", "GET", null));
    Check("provider-specific mutation and encoded separator denied", () => { Denied(() => ApiPolicy.Validate("/providers/proxies/p/n/healthcheck", "POST", null)); Denied(() => ApiPolicy.Validate("/providers/proxies/p/a%2fb/healthcheck", "GET", null)); });
    Check("controller reload denied", () => Denied(() => ApiPolicy.Validate("/configs", "PUT", JsonNode.Parse("{\"path\":\"C:/secret\"}"))));
    Check("controller upgrade denied", () => Denied(() => ApiPolicy.Validate("/upgrade", "POST", null)));
    Check("controller restart denied", () => Denied(() => ApiPolicy.Validate("/restart", "POST", null)));
    Check("safe mode mutation allowed", () => ApiPolicy.Validate("/configs", "PATCH", JsonNode.Parse("{\"mode\":\"rule\",\"tun\":{\"enable\":false}}")));
    Check("controller injection via PATCH denied", () => Denied(() => ApiPolicy.Validate("/configs", "PATCH", JsonNode.Parse("{\"external-controller\":\"0.0.0.0:1\"}"))));
    Check("TUN route mutation denied", () => Denied(() => ApiPolicy.Validate("/configs", "PATCH", JsonNode.Parse("{\"tun\":{\"enable\":true,\"device\":\"other\"}}"))));
    Check("proxy selection allowed", () => ApiPolicy.Validate("/proxies/Local%20Group", "PUT", JsonNode.Parse("{\"name\":\"DIRECT\"}")));
    Check("extra proxy mutation denied", () => Denied(() => ApiPolicy.Validate("/proxies/p", "PUT", JsonNode.Parse("{\"name\":\"x\",\"path\":\"bad\"}"))));
    Check("connection close allowed", () => ApiPolicy.Validate("/connections/fixture-id", "DELETE", null));
    Check("encoded path traversal denied", () => Denied(() => ApiPolicy.Validate("/proxies/%2e%2e/configs", "PUT", JsonNode.Parse("{\"name\":\"x\"}"))));
    Directory.CreateDirectory(dir);
    byte[] Image(ushort machine = 0x8664, ushort flags = 2) { var bytes = new byte[512]; using var stream = new MemoryStream(bytes); using var writer = new BinaryWriter(stream); writer.Write((ushort)0x5a4d); stream.Position = 0x3c; writer.Write(128); stream.Position = 128; writer.Write(0x00004550); writer.Write(machine); stream.Position = 150; writer.Write(flags); writer.Write((ushort)0x20b); return bytes; }
    var source = Path.Combine(dir, "selected.exe"); var target = Path.Combine(dir, "mihomo.exe");
    File.WriteAllBytes(source, Image()); var imageHash = CoreImage.Hash(source);
    Check("selected core hashed and staged from exact image", () => { var staged = target + ".test"; CoreImage.Stage(source, staged, imageHash); if (!File.ReadAllBytes(staged).SequenceEqual(File.ReadAllBytes(source))) throw new Exception(); File.Delete(staged); });
    Check("changed source hash denied before privileged copy", () => Denied(() => CoreImage.Stage(source, target + ".bad-hash", new string('0',64))));
    Check("non-PE core denied", () => { var bad = Path.Combine(dir, "bad.exe"); File.WriteAllBytes(bad,new byte[512]); Denied(() => CoreImage.Stage(bad,target + ".bad-image",CoreImage.Hash(bad))); });
    Check("non-x64 core denied", () => { var bad=Path.Combine(dir,"arm.exe"); File.WriteAllBytes(bad,Image(0xaa64)); Denied(() => CoreImage.Stage(bad,target + ".arm-image",CoreImage.Hash(bad))); });
    Check("DLL core denied", () => { var bad=Path.Combine(dir,"dll.exe"); File.WriteAllBytes(bad,Image(0x8664,0x2002)); Denied(() => CoreImage.Stage(bad,target + ".dll-image",CoreImage.Hash(bad))); });
    Check("existing staging file never overwritten", () => { var staged=target+".existing"; File.WriteAllText(staged,"preserved"); Denied(() => CoreImage.Stage(source,staged,imageHash)); if(File.ReadAllText(staged)!="preserved") throw new Exception(); });
    Check("selected core rollback restores prior image", () => { File.WriteAllText(target,"previous"); var starts=0; var stops=0; try { CoreImage.Replace(source,target,imageHash,()=>stops++,()=>{if(++starts==1) throw new IOException("Injected start failure");}); throw new Exception("Expected start failure"); } catch(IOException){} if(File.ReadAllText(target)!="previous" || starts!=2 || stops!=2) throw new Exception(); });
    Check("selected core swap starts verified image", () => { var stopped=false; CoreImage.Replace(source,target,imageHash,()=>stopped=true,()=>{if(!stopped || CoreImage.Hash(target)!=imageHash) throw new Exception();}); if(Directory.EnumerateFiles(dir,"mihomo.exe.*-*").Any()) throw new Exception("Left transaction files"); });
    Check("source symlink denied", () => { var link=Path.Combine(dir,"link.exe"); File.CreateSymbolicLink(link,source); Denied(()=>CoreImage.Stage(link,target+".link-image",imageHash)); });
    if(OperatingSystem.IsWindows()) Check("Windows writer is denied during image approval", () => { using var writer=new FileStream(source,FileMode.Open,FileAccess.Write,FileShare.ReadWrite); Denied(()=>CoreImage.Stage(source,target+".writer-image",imageHash)); });
    Console.WriteLine($"Service policy: {passed} checks passed");
} finally { if (Directory.Exists(dir)) Directory.Delete(dir, true); }
